import * as THREE from "three";

import { applyCosmeticTransform } from "./applyCosmeticTransform";
import { buildBoneTree, type BoneTree } from "./buildBoneTree";
import type { LoadedCosmetic } from "./loadCosmetic";
import { steveGeoForVariant, type SteveModelVariant } from "./steveGeo";
import type { Vec3 } from "./types";

export const RIG_RENDERER_SETTINGS = {
  toneMapping: THREE.ACESFilmicToneMapping,
  outputColorSpace: THREE.SRGBColorSpace,
} as const;

export interface SteveRig {
  tree: BoneTree;
  material: THREE.MeshStandardMaterial;
  pivots: Map<string, Vec3>;
  restPositions: Map<string, Vec3>;
  dispose(): void;
}

export interface BonePose {
  rotation?: Vec3;
  position?: Vec3;
  scale?: Vec3;
}

export interface BonePoseOptions {
  negateX?: boolean;
}

export function createSteveRig(variant: SteveModelVariant): SteveRig {
  const material = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    side: THREE.DoubleSide,
    alphaTest: 0.5,
    roughness: 0.9,
    metalness: 0,
  });

  const geo = steveGeoForVariant(variant);
  const tree = buildBoneTree(geo, material, { armorOnly: false });
  const pivots = new Map<string, Vec3>(
    geo.bones.map((b) => [b.name, b.pivot ?? [0, 0, 0]])
  );

  const restPositions = new Map<string, Vec3>();
  for (const [name, bone] of tree.bones) {
    restPositions.set(name, [bone.position.x, bone.position.y, bone.position.z]);
  }

  return {
    tree,
    material,
    pivots,
    restPositions,
    dispose() {
      tree.root.traverse((o) => {
        if (o instanceof THREE.Mesh) o.geometry.dispose();
      });
      material.map?.dispose();
      material.dispose();
    },
  };
}

export function configureSkinTexture(texture: THREE.Texture): THREE.Texture {
  texture.flipY = false;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.magFilter = THREE.NearestFilter;
  texture.minFilter = THREE.NearestFilter;
  texture.generateMipmaps = false;
  texture.needsUpdate = true;
  return texture;
}

export function loadSkinTexture(url: string): Promise<THREE.Texture> {
  return new Promise((resolve, reject) => {
    new THREE.TextureLoader().load(
      url,
      (texture) => resolve(configureSkinTexture(texture)),
      undefined,
      () => reject(new Error(`Failed to load skin texture: ${url}`))
    );
  });
}

export const IDLE_POSE: Record<string, BonePose> = {
  bipedHead: { rotation: [0, -10, 0] },
  bipedRightArm: { rotation: [0, 0, 5] },
  bipedLeftArm: { rotation: [0, 0, -5] },
  bipedRightLeg: { rotation: [-7.5, 20, 0] },
  bipedLeftLeg: { rotation: [0, -10, 0] },
};

const DEG_TO_RAD = Math.PI / 180;
const POSE_EULER = new THREE.Euler(0, 0, 0, "ZYX");

export function applyBonePose(
  rig: Pick<SteveRig, "tree" | "restPositions">,
  poses: Record<string, BonePose>,
  options: BonePoseOptions = {}
): void {
  const negateX = options.negateX ?? true;

  for (const [name, pose] of Object.entries(poses)) {
    const bone = rig.tree.bones.get(name);
    if (!bone) continue;

    if (pose.rotation) {
      const [x, y, z] = pose.rotation;
      POSE_EULER.set(
        (negateX ? -x : x) * DEG_TO_RAD,
        (negateX ? -y : y) * DEG_TO_RAD,
        z * DEG_TO_RAD,
        "ZYX"
      );
      bone.quaternion.setFromEuler(POSE_EULER);
    }

    if (pose.position) {
      const rest = rig.restPositions.get(name) ?? [0, 0, 0];
      const [x, y, z] = pose.position;
      bone.position.set(
        negateX ? rest[0] - x : rest[0] + x,
        rest[1] + y,
        rest[2] + z
      );
    }

    if (pose.scale) bone.scale.set(...pose.scale);
  }
}

export function mountCosmeticOnRig(
  cosmetic: LoadedCosmetic,
  rig: Pick<SteveRig, "tree" | "pivots">,
  variant: SteveModelVariant
): () => void {
  applyCosmeticTransform(cosmetic);

  const cosmeticPivots = new Map<string, Vec3>(
    cosmetic.geo.bones.map((b) => [b.name, b.pivot ?? [0, 0, 0]])
  );

  const wantSlim = variant === "slim";
  const moved: Array<{ parent: THREE.Object3D; child: THREE.Object3D }> = [];
  const hidden: THREE.Object3D[] = [];

  for (const [name, cosBone] of cosmetic.tree.bones) {
    if (!name.toLowerCase().startsWith("armor")) continue;
    if (cosBone.children.length === 0) continue;

    const isSlimArm = /armslim$/i.test(name);
    const isThickArm = /^armor(left|right)arm$/i.test(name);
    if (isSlimArm && !wantSlim) {
      cosBone.visible = false;
      hidden.push(cosBone);
      continue;
    }
    if (isThickArm && wantSlim) {
      const slim = cosmetic.tree.bones.get(name + "Slim");
      if (slim && slim.children.length > 0) {
        cosBone.visible = false;
        hidden.push(cosBone);
        continue;
      }
    }

    const steveName = rig.tree.bones.has(name)
      ? name
      : name.replace(/Slim$/i, "");
    const steveBone = rig.tree.bones.get(steveName);
    if (!steveBone) continue;

    steveBone.add(cosBone);
    const cp = cosmeticPivots.get(name) ?? [0, 0, 0];
    const sp = rig.pivots.get(steveName) ?? cp;
    cosBone.position.set(sp[0] - cp[0], cp[1] - sp[1], cp[2] - sp[2]);
    moved.push({ parent: steveBone, child: cosBone });
  }

  return () => {
    for (const m of moved) m.parent.remove(m.child);
    for (const h of hidden) h.visible = true;
  };
}
